// SVP carts (the SVP chip: a Samsung SSP1601 DSP with 128KB of
// DRAM on the cartridge) in a recompiled Genesis cart. The chip is
// genesis_plus_gx's own cart_hw/svp/svp.c + ssp16.c compiled to WAT
// (gpgx-svp.json, generated by scripts/recompile-gen/gpgx-svp.mjs): the
// SSP1601 interpreter runs the DSP program from the cartridge ROM and its
// IRAM exactly as the reference does. This file wires the unit where gpgx
// wires it:
//
//   md_cart.c md_cart_init     svp_init when the header has 'SV' at $1C8
//   md_cart.c md_cart_reset    svp_reset (IRAM/ROM copy, SSP1601 reset)
//   system.c system_frame_gen  ssp1601_run(SVP_cycles = 800) after the
//                              68000 and Z80 have run each line
//   svp.c svp_init             68000 banks $30-$31 (DRAM, with the $30FE06 /
//                              $30FE08 wait releases on word writes) and $39 /
//                              $3A (the two "cell arrange" read windows): the
//                              cart's CARTMAP codes SVP_DRAM / SVP_CELL route
//                              the 68000, the Z80 bank window and VDP DMA there
//   mem68k.c case 0x50         $A15000-$A150FF: XST and the PM0 status
//   vdp_ctrl.c vdp_68k_ctrl_w  a 68000-bus DMA with reg[23] & $60 clear starts
//                              one word late (addr += reg[15], length - 1)
//
// LICENSE: the SVP code is by notaz for Genesis Plus GX, free for
// non-commercial use only; carts built with it are non-commercial (NOTICE).
//
// Plain JS ESM + JSDoc.

import { readFileSync } from "node:fs";
import { placeUnit } from "../wasm-unit.js";

let DATA = null;
const data = () => (DATA ??= JSON.parse(readFileSync(new URL("./gpgx-svp.json", import.meta.url), "utf8")));

/** CARTMAP codes for the SVP banks (below the backup RAM / mapper codes -1..-4). */
export const SVP_DRAM = -8;
export const SVP_CELL = -9;
/** system.c SVP_cycles: SSP1601 instructions run after every line. */
export const SVP_CYCLES = 800;

/**
 * md_cart_init: READ_BYTE(cart.rom, 0x1c8) == 'S' && READ_BYTE(cart.rom, 0x1c9) == 'V'.
 * @param {Uint8Array} img normalised ROM
 */
export function hasSvp(img) {
  return img.length > 0x1c9 && img[0x1c8] === 0x53 && img[0x1c9] === 0x56;
}

/** Bytes of linear memory the unit needs (data, .bss with the 2MB cart.rom copy, C stack). */
export function svpUnitSize() {
  return data().units.svp.size;
}

/** gpgx-svp.json's provenance (gpgx commit, source hashes, compiler, the broken control's edit). */
export function svpProvenance() {
  return data().provenance;
}

const fn = (unit, name) => {
  const f = data().units[unit].exports[name];
  if (!f) throw new Error(`genesis recompile: the SVP unit exports no ${name}`);
  return f;
};

/**
 * The cart's view of the SVP memory, for the romdev.recompile section:
 * linear-memory regions compared with genesis_plus_gx's genesis_svp_* regions.
 * @param {number} base the unit's linear address
 */
export function svpRegions(base) {
  const L = data().layout;
  const at = base + L.svp;
  return {
    svp_dram: { offset: at + L.dram, length: L.dramSize, ref: "genesis_svp_dram" },
    svp_iram: { offset: at + L.iram, length: L.iramSize, ref: "genesis_svp_iram" },
    svp_ssp: { offset: at + L.ssp, length: L.sspSize, ref: "genesis_svp_ssp" },
  };
}

/**
 * The unit and the cart's wrappers around it.
 * @param {number} base   linear address of the unit's memory
 * @param {{romimg:number, romsize:number, broken?:boolean}} o
 *   broken: options.svpBreak, the must-fail control unit (one SSP opcode wrong)
 */
export function svpWat(base, o) {
  const unit = o.broken ? "svp_break" : "svp";
  const u = data().units[unit];
  const f = (n) => fn(unit, n);
  return placeUnit(u, base, `genesis_plus_gx SVP unit '${unit}' (gpgx-svp.json)`) + `

  ;; ---- SVP wiring (svp.js)
  ;; md_cart_init's svp_init + md_cart_reset's svp_reset, at power-on
  (func $svp_power_on${u.start ? `
    (call ${u.start})` : ""}
    (call ${f("romdev_svp_init")} (i32.const ${o.romimg}) (i32.const ${o.romsize}))
    (call ${f("romdev_svp_reset")}))
  ;; system_frame_gen: ssp1601_run(SVP_cycles) after each line's 68000 and Z80 run
  (func $svp_line (call ${f("romdev_svp_run")} (i32.const ${SVP_CYCLES})))
  ;; m68ki_read_8/16, m68ki_write_8/16 on banks $30/$31 (DRAM) and $39/$3A (cell arrange reads)
  (func $svp_rd8 (param $a i32) (result i32) (call ${f("romdev_svp_read8")} (local.get $a)))
  (func $svp_rd16 (param $a i32) (result i32) (call ${f("romdev_svp_read16")} (local.get $a)))
  (func $svp_wr8 (param $a i32) (param $v i32) (call ${f("romdev_svp_write8")} (local.get $a) (local.get $v)))
  (func $svp_wr16 (param $a i32) (param $v i32) (call ${f("romdev_svp_write16")} (local.get $a) (local.get $v)))
  ;; mem68k.c ctrl_io_read_byte / _word, ctrl_io_write_word case 0x50 (-1 / 0 = not an SVP register)
  (func $svp_ctrl_r8 (param $a i32) (result i32) (call ${f("romdev_svp_ctrl_r8")} (local.get $a)))
  (func $svp_ctrl_r16 (param $a i32) (result i32) (call ${f("romdev_svp_ctrl_r16")} (local.get $a)))
  (func $svp_ctrl_w16 (param $a i32) (param $v i32) (result i32) (call ${f("romdev_svp_ctrl_w16")} (local.get $a) (local.get $v)))
`;
}
